  const config = { schemaIds: 'builtin:management-zones'};
  const objects = await settingsObjectsClient.getSettingsObjects(config);
  let managementZones = objects.items.map(el => el.value.name);
  managementZones = ["Tenant", ...managementZones]
  return managementZones;
}

timeseries {
  inputa=avg(dt.sfm.active_gate.jvm.cpu_usage)
  }, by: { 
    dt.network_zone.id 
  } 
| fieldsAdd nzordflt = if(isNull(dt.network_zone.id), "default", else: dt.network_zone.id)
| summarize distinctNetworkZones = collectDistinct(nzordflt)
| append [data record(distinctNetworkZones="ANY")]
| fieldsAdd distinctNetworkZones

data record( dt.active_gate.id="ANY")
| append [timeseries avg(dt.sfm.active_gate.jvm.cpu_usage), 
  by: { dt.active_gate.group.name, dt.network_zone.id, dt.active_gate.id, host.name }

// add extra columns to deal with null/default dimensions
