import { metricsClient  } from '@dynatrace-sdk/client-classic-environment-v2';

export default async function() {
  // Check if that tile should be activated based on selected indicators and scope
  if($Indicators[0] === "All" || $Indicators.includes("accessTokens")) {
    if($Scope[0] === "Tenant") {
      // For each app, determine if there's any conversion rate captured in the last 7 days
      let config = { from: "now-7d", acceptType: "application/json; charset=utf-8", metricSelector: 'dsfm:active_gate.rest.request_count:splitBy(operation):sort(value(auto,descending)):limit(5):fold(value)'};
      let objects = await metricsClient.query(config);
      // Prepare template for graph visualization
      const apiStats = {
        records: [],
        types: [
          {
            mappings: {
              api: {
                type: "string"
              },
              calls: {
                type: "long"
              }
            },
            indexRange: [
              0,
              1
            ]
          }
        ]
      };
      // Get calls count for each API endpoint
      for(let api of objects.result[0].data) {
        let apiStatsIndex = apiStats.records.findIndex(el => el.api === api.dimensionMap.operation);
        apiStats.records.push({
          api: api.dimensionMap.operation,
          calls: api.values[0]
        })
      }
      return apiStats;
    } else {
      return "N/A";
    }
  } else {
    return "N/A";
  }
}

