import { problemsClient } from '@dynatrace-sdk/client-classic-environment-v2';

export default async function() {
  // Check if that tile should be activated based on selected indicators and scope
  if($Indicators[0] === "All" || $Indicators.includes("metricEvents")) {
    if($Scope[0] === "Tenant") {
      let scope;
      if($Scope[0] === "Tenant") {
        scope = 'Tenant';
      } else {
        let mzList = "";
        for(let i=0; i<$Scope.length; i++) {
          mzList += i === 0 ? `"${$Scope[i]}"` : `,"${$Scope[i]}"`;
        }
        scope = mzList;
      }
      let config;
      if(scope === "Tenant") {
        config = { from: "now-7d", pageSize: 500};
      } else {
        const problemSelector = `managementZones(${scope})`;
        config = { from: "now-7d", problemSelector: problemSelector, pageSize: 500};
      }
      // Get all problems open in the past 7 days
      let objects = await problemsClient.getProblems(config);
      let problems = objects.problems;
      while(objects.nextPageKey) {
        config = { nextPageKey: objects.nextPageKey };
        objects = await problemsClient.getProblems(config);
        problems = [...problems, ...objects.problems];
      }
      // Format the results for graph visualization
      const severityLevelStats = {
        records: [],
        types: [
          {
            mappings: {
              severityLevel: {
                type: "string"
              },
              count: {
                type: "long"
              }
            },
            indexRange: [
              0,
              1
            ]
          }
        ]
      };
      // For each problem, increment the count of problems per severity
      for(let problem of problems) {
        let severityLevelIndex = severityLevelStats.records.findIndex(el => el.severityLevel === problem.severityLevel);
        if(severityLevelIndex > -1) {
          severityLevelStats.records[severityLevelIndex].count++;
        } else {
          severityLevelStats.records.push({
            severityLevel: problem.severityLevel,
            count: 1
          })
        }
      }
      return severityLevelStats;
    } else {
      return "N/A";
    }
  } else {
    return "N/A";
  }
}

