const startTime = Date.now();
let timedOut = false;

// Function to add warnings to the We app name if that's the default catch-all app
function filterEntry(el) {
  const filteredEntry = {};
  filteredEntry["Monitored apps:"] = el.displayName === "My web application" ? "⚠️ My web application ⚠️" : el.displayName;
  return filteredEntry;
}

// Helper function to filter unique names
function onlyUnique(value, index, array) {
  return array.indexOf(value) === index;
}

// Helper sorting function
function sortArrayOfObjects(arr, propertyName, order = 'ascending') {
  const sortedArr = arr.sort((a, b) => {
    if (a[propertyName] < b[propertyName]) {
      return -1;
    }
    if (a[propertyName] > b[propertyName]) {
      return 1;
    }
    return 0;
  });

  if (order === 'descending') {
    return sortedArr.reverse();
  }

  return sortedArr;
};

// Function that returns the result of evaluating an indicator
async function evaluate(indicator, $Scope) {
  const score = await indicator($Scope);
  const weight = indicatorWeights[indicator.name];
  let recommendation = indicatorRecommendations.find(e => e.indicator === indicator.name)[score];
  return {
    indicator: indicator.name,
    weight: weight,
    score: score,
    recommendation: recommendation
  };
}

// Function to get the maximum total score expected for a selection of indicators
function getMaxWeightedTotalScore(indicators) {
  let maxWeightedTotalScore = 0;
  for(let indicator of indicators) {
    maxWeightedTotalScore += indicatorWeights[indicator.name]
  }
  return maxWeightedTotalScore;
}

// Function to count objects per scope (Dynatrace Settings Limits)
function processObjects(accumulator, objects) {
  for(let object of objects.items) {
    let scopeCounter = accumulator.filter(el => el.scope === object.scope)[0];
    if(scopeCounter) { // In a previous loop iteration, at least one object already got counted for that current object's scope
      scopeCounter.objectCount += 1;
    } else {
      accumulator.push({
        scope: object.scope,
        objectCount: 1
      });
    }
  }
}

