        if(Date.now() - startTime < 10000) {
        config = { nextPageKey: objects.nextPageKey };
        objects = await settingsObjectsClient.getSettingsObjects(config);
        processObjects(schemaScopes, objects);     
        } else {
          timedOut = true;
          objects.nextPageKey = null;
        }
      }
      let sortedScopes = schemaScopes.sort(function (a, b) {
        if (a.objectCount < b.objectCount) {
          return 1;
        }
        if (a.objectCount > b.objectCount) {
          return -1;
        }
        return 0;
      });
      // console.log(schemaScopes);
      // console.log(sortedScopes);
      // Total object count for that schema
      let totalObjects = ``;
      const info = `${objects.totalCount} (${Math.round((objects.totalCount / 500000) * 100 * 10) / 10}%)`
      if((objects.totalCount / 500000) * 100 >= riskThreshold) {
        totalObjects = `⚠️ ${info}`;
        riskThresholdsBreached++;
      } else if((objects.totalCount / 500000) * 100 >= warningThreshold) {
        totalObjects = `💡 ${info}`;
        warningThresholdsBreached++;
      } else {
        totalObjects = `✅ ${info}`;
      }
      // Tenant-level object count for that schema
      const tenantLimitConsumption = sortedScopes.filter(el => el.scope === 'environment')[0];
      let tenantLevelObjects = ``;
      if(tenantLimitConsumption) {
        const info = `${tenantLimitConsumption.objectCount} (${Math.round((tenantLimitConsumption.objectCount / limit) * 100 * 10) / 10}%)`
        if((tenantLimitConsumption.objectCount / limit) * 100 >= riskThreshold) {
          tenantLevelObjects = `⚠️ ${info}`;
          riskThresholdsBreached++;
        } else if((tenantLimitConsumption.objectCount / limit) * 100 >= warningThreshold) {
          tenantLevelObjects = `💡 ${info}`;
          warningThresholdsBreached++;
        } else {
          tenantLevelObjects = `✅ ${info}`;
        }
      }
      // Host group with the biggest object count for that schema
      const topHostGroupLimitConsumption = sortedScopes.filter(el => el.scope && el.scope.indexOf('HOST_GROUP') === 0)[0];
      let topHostGroupObjects = ``;
      if(topHostGroupLimitConsumption) {
        const info = `${topHostGroupLimitConsumption.objectCount} (${Math.round((topHostGroupLimitConsumption.objectCount / limit) * 100 * 10) / 10}%) ${topHostGroupLimitConsumption.scope}`
        if((topHostGroupLimitConsumption.objectCount / limit) * 100 >= riskThreshold) {
          topHostGroupObjects = `⚠️ ${info}`;
          riskThresholdsBreached++;
        } else if((topHostGroupLimitConsumption.objectCount / limit) * 100 >= warningThreshold) {
          topHostGroupObjects = `💡 ${info}`;
          warningThresholdsBreached++;
        } else {
          topHostGroupObjects = `✅ ${info}`;
        }
      }
      // Host with the biggest object count for that schema
      const topHostLimitConsumption = sortedScopes.filter(el => el.scope && el.scope.indexOf('HOST-') === 0)[0];
      let topHostObjects = ``;
      if(topHostLimitConsumption) {
        const info = `${topHostLimitConsumption.objectCount} (${Math.round((topHostLimitConsumption.objectCount / limit) * 100 * 10) / 10}%) ${topHostLimitConsumption.scope}`
        if((topHostLimitConsumption.objectCount / limit) * 100 >= riskThreshold) {
          topHostObjects = `⚠️ ${info}`;
          riskThresholdsBreached++;
        } else if((topHostLimitConsumption.objectCount / limit) * 100 >= warningThreshold) {
          topHostObjects = `💡 ${info}`;
          warningThresholdsBreached++;
        } else {
          topHostObjects = `✅ ${info}`;
        }
      }
      limits.push({
        schemaId: setting.schemaId,
        maxObjectsPerSchema: 500000,
        totalObjects: totalObjects,
        maxObjectsPerScope: limit,
        tenantLevelObjects: tenantLevelObjects,
        topHostGroupObjects: topHostGroupObjects,
        topHostObjects: topHostObjects
      })
    }
  }
  // Compute local score based on number of alert, warning and good thresholds
  const score = riskThresholdsBreached > 0 ? 0 : (warningThresholdsBreached > 0 ? 0.5 : 1);
  return score;
}

export default async function() {
  const evaluations = [];
  // Determine what indicators should be evaluated based on the selected DTR scope
  let scopedIndicators;
  if($Scope[0] === "Tenant") {
    scopedIndicators = tenantIndicators;
  } else {
    scopedIndicators = managementZoneIndicators;
  }
  // Determine what indicators should be evaluated based on the selected indicators
  let selectedIndicators = [];
  if($Indicators[0] === "All") {
    selectedIndicators = scopedIndicators;
  } else {
    for(let scopedIndicator of scopedIndicators) {
      if($Indicators.includes(scopedIndicator.name)) {
        selectedIndicators.push(scopedIndicator); 
      }
    }
  }
  // Evaluate indicators
  for(let selectedIndicator of selectedIndicators) {
    const evaluation = await evaluate(selectedIndicator, $Scope);
    evaluations.push(evaluation);
  }
  // Filter out healthy indicators
  const filteredEvaluations = evaluations.filter(e => e.score !== 1);
  // Segment indicators per importance
  const importantIndicatorEvaluations = filteredEvaluations.filter(e => e.weight === 1);
  const bestPracticeIndicatorEvaluations = filteredEvaluations.filter(e => e.weight === 2);
  const fundamentalIndicatorEvaluations = filteredEvaluations.filter(e => e.weight === 3);
  // Sort each population per normalized score
  const sortedImportantIndicatorEvaluations = sortArrayOfObjects(importantIndicatorEvaluations, "score");
  const sortedBestPracticeIndicatorEvaluations = sortArrayOfObjects(bestPracticeIndicatorEvaluations, "score");
  const sortedFundamentalIndicatorEvaluations = sortArrayOfObjects(fundamentalIndicatorEvaluations, "score");
  // Concatenate groups of evaluations by order of importance
  const finalEvaluations = sortedFundamentalIndicatorEvaluations;
  finalEvaluations.push(...sortedBestPracticeIndicatorEvaluations);
  finalEvaluations.push(...sortedImportantIndicatorEvaluations);
  console.log(finalEvaluations);
  // Extract the recommendation from each evaluation
  const prioritizedRecommendations = finalEvaluations.map(e => {
    return {
      "Prioritized next steps 👇": e.recommendation,
      "Importance": e.weight === 3 ? "Fundamentals" : (e.weight === 2 ? "Best practice" : "Recommended")
    };
  });
  // Return prioritized recommendations
  return prioritizedRecommendations.length > 0 ? prioritizedRecommendations : { "Prioritized next steps 👇": "✅ Well done! All recommendations have been implemented 👏"};
}

